// Decide which watchlist rows are due now, and reset state if the condition or URL changed.
const cfg = $('Config').first().json;
const now = $now.toUTC();
const hash = (s) => { let h = 5381; for (const c of String(s)) h = ((h << 5) + h + c.charCodeAt(0)) >>> 0; return h.toString(16); };

const rows = $input.all().map((i) => i.json).filter((r) => r.watch_id && r.url && r.condition);
const due = [];
for (const r of rows) {
  const every = Number(r.check_every_hours) || 24;
  const nextDue = r.next_due_at ? new Date(r.next_due_at) : null;
  // A row due within the next few minutes counts as due now. Without this, a row whose next check
  // lands a few seconds after the hour is skipped by that run and only picked up an hour later,
  // so check_every_hours = 1 would quietly become every two hours.
  const grace = 5 * 60 * 1000;
  if (nextDue && !isNaN(nextDue) && nextDue.getTime() - grace > now.toJSDate().getTime()) continue;

  const h = hash(String(r.url).trim() + '|' + String(r.condition).trim());
  const changed = r.condition_hash && r.condition_hash !== h;
  due.push({
    ...r,
    fetch_mode: String(r.fetch_mode || 'auto').toLowerCase(),
    check_every_hours: every,
    stable_verdict: changed ? 'UNKNOWN' : (r.stable_verdict || 'UNKNOWN'),
    yes_streak: changed ? 0 : Number(r.yes_streak) || 0,
    no_streak: changed ? 0 : Number(r.no_streak) || 0,
    error_count: Number(r.error_count) || 0,
    condition_hash: h,
    state_reset: !!changed,
  });
  if (due.length >= (Number(cfg.maxItemsPerRun) || 10)) break;
}
return due.map((r) => ({ json: r }));

// Turn the HTTP response into plain text, and decide whether it is usable.
const cfg = $('Config').first().json;
const row = $('Pick rows that are due').item.json;
const res = $json;
const status = Number(res.statusCode) || 0;
const ctype = String((res.headers && (res.headers['content-type'] || res.headers['Content-Type'])) || '').toLowerCase();
let body = res.body;

let text = '';
if (body && typeof body === 'object') {
  text = JSON.stringify(body, null, 1);
} else {
  let h = String(body || '');
  const title = (h.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [,''])[1];
  h = h.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ');
  h = h.replace(/<\/(p|div|li|tr|h\d|br|td|th|section|article)>/gi, '\n').replace(/<[^>]+>/g, ' ');
  h = h.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'");
  text = (title ? 'TITLE: ' + title.trim() + '\n' : '') + h.replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
}

const tooShort = text.length < (Number(cfg.minBodyChars) || 400);
let fetch_status = 'ok';
let fetch_error = '';
if ([403, 429, 503].includes(status) && row.fetch_mode === 'auto') { fetch_status = 'needs_browser'; fetch_error = 'HTTP ' + status + ' - the site blocks automated requests; using a browser'; }
else if (status >= 400 || status === 0) { fetch_status = 'fail'; fetch_error = 'HTTP ' + status; }
else if (/login|sign in|ログイン/i.test(text.slice(0, 600)) && tooShort) { fetch_status = 'fail'; fetch_error = 'Login page returned'; }
else if (tooShort) { fetch_status = row.fetch_mode === 'auto' ? 'needs_browser' : 'fail'; fetch_error = 'Body too short (' + text.length + ' chars) - page is probably rendered by JavaScript'; }

return { json: { ...row, fetch_mode_used: 'http', fetch_status, fetch_error, http_status: status, content_type: ctype, source_text: text.slice(0, 40000) } };

// Normalise the Airtop scrape into the same shape as the HTTP branch.
const row = $('Pick rows that are due').item.json;
const r = $('Airtop: read page').item.json || {};
const mr = (r.data && r.data.modelResponse) || r.modelResponse || null;
const sc = (mr && typeof mr === 'object' && mr.scrapedContent) || r.scrapedContent || (r.data && r.data.scrapedContent) || null;
let text = (sc && sc.text) || (typeof mr === 'string' ? mr : '') || (r.data && r.data.text) || r.text || r.content || r.markdown || '';
if (typeof text !== 'string') text = JSON.stringify(text, null, 1);
// Airtop returns markdown: undo its escaping so quotes match the real page text
text = text.replace(/\\([\[\]_*`#()])/g, '$1');
// Drop images and link URLs (keep the link text) - they carry no meaning and push the real content past the size cap
text = text.replace(/!\[[^\]]*\]\([^)]*\)/g, ' ').replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/https?:\/\/\S+/g, ' ');
text = text.replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
const ok = text && text.length > 50;
return { json: { ...row, fetch_mode_used: 'browser', fetch_status: ok ? 'ok' : 'fail', fetch_error: ok ? '' : 'Browser returned no readable text', source_text: String(text).slice(0, 120000) } };

