// One place decides what happens next: state transitions, notification, and what to write back.
const cfg = $('Config').first().json;
const inp = $input.item.json;
// Was this a fetch failure, or a judgement?
const judged = inp && inp.output && typeof inp.output === 'object';
// The row (and the fetched text) travel with the item, so no deep pairing is needed
let row = inp;
if (judged) {
  // The judge only outputs its answer; the row and the page text live on the item that fed it.
  row = null;
  for (const src of ['Extract text (browser)', 'Extract text (HTTP)']) {
    try { const c = $(src).item.json; if (c && c.watch_id) { row = c; break; } } catch (e) {}
  }
  if (!row) throw new Error('Could not find the watch row that fed the judge');
}
const now = $now.toUTC();
const nowIso = now.toISO();
const every = Number(row.check_every_hours) || 24;
const nextDue = (hours) => now.plus({ hours }).toISO();

// The browser lane always passes through the judge, even when the scrape came back empty: treat that as a fetch failure, not a judgement
const browserFailed = judged && row.fetch_status === 'fail';
const fetchStatus = judged && !browserFailed ? 'ok' : (row.fetch_status || inp.fetch_status || 'fail');
const fetchError  = judged && !browserFailed ? '' : (row.fetch_error || inp.fetch_error || 'unknown');
const modeUsed    = row.fetch_mode_used || row.fetch_mode;
const sourceText  = judged ? String(row.source_text || '') : '';
const norm = (s) => String(s).replace(/\\([\[\]_*`#()])/g, '$1').replace(/\s+/g, '').toLowerCase();
const normSource = norm(sourceText);
const bare = (s) => String(s).toLowerCase().replace(/[^a-z0-9\u3040-\u30ff\u4e00-\u9fff]/g, '');
const bareSource = bare(sourceText);
// A quote counts if it really appears in the page. Short quotes like '10○' are legitimate, so only empty or one-character quotes are rejected.
const quoteFound = (q) => { const nq = norm(q), bq = bare(q); return (nq.length >= 2 && normSource.includes(nq)) || (bq.length >= 4 && bareSource.includes(bq)); };

let stable = row.stable_verdict || 'UNKNOWN';
let yes = Number(row.yes_streak) || 0, no = Number(row.no_streak) || 0, err = Number(row.error_count) || 0;
let verdict = 'FETCH_FAILED', confidence = 0, evidence = [], reason = fetchError;
let notify = false, notifyKind = '', lastSuccess = row.last_success_at || '', nextDueAt = nextDue(every);

if (judged && !browserFailed) {
  const o = inp.output;
  verdict = String(o.verdict || '').toUpperCase();
  confidence = Number(o.confidence);
  evidence = Array.isArray(o.evidence) ? o.evidence.map(String) : [];
  reason = String(o.reason || '');
  // Validate what the model said. Evidence must really be in the page.
  const valid = ['YES', 'NO', 'UNCLEAR'].includes(verdict)
    && !isNaN(confidence) && confidence >= 0 && confidence <= 1
    && (verdict === 'UNCLEAR' || (evidence.length > 0 && evidence.every(quoteFound)));
  if (!valid) { verdict = 'MODEL_INVALID'; reason = 'Model output failed validation (bad enum, bad confidence, or quotes not found in page)'; }
  if (verdict === 'YES' && confidence < 0.7) verdict = 'UNCLEAR';
}

if (verdict === 'YES' || verdict === 'NO') {
  err = 0; lastSuccess = nowIso;
  if (stable === 'UNKNOWN') { stable = verdict; yes = 0; no = 0; }         // baseline: record, do not notify
  else if (verdict === 'YES') {
    no = 0; yes += 1;
    if (stable === 'NO' && yes >= (Number(cfg.yesConfirmationsToNotify) || 1)) { stable = 'YES'; notify = true; notifyKind = 'condition_met'; }
  } else {
    yes = 0; no += 1;
    if (stable === 'YES' && no >= (Number(cfg.noConfirmationsToRearm) || 2)) { stable = 'NO'; }  // re-armed, silently
  }
} else {
  // UNCLEAR / MODEL_INVALID / FETCH_FAILED: keep the stable verdict, count the problem, back off a little
  err += 1;
  nextDueAt = nextDue(Math.min(every * (err >= 3 ? 2 : 1), 48));
  if (err === (Number(cfg.errorsBeforeAlert) || 3)) { notify = true; notifyKind = 'monitoring_problem'; }
}

const to = row.notify_to || cfg.notifyEmail;
return { json: {
  // for the Watchlist update
  watch_id: row.watch_id, stable_verdict: stable, yes_streak: yes, no_streak: no, error_count: err,
  last_checked_at: nowIso, last_success_at: lastSuccess, next_due_at: nextDueAt,
  last_evidence: evidence.join(' | ').slice(0, 500), last_error: verdict === 'FETCH_FAILED' || verdict === 'MODEL_INVALID' || verdict === 'UNCLEAR' ? reason.slice(0, 300) : '',
  condition_hash: row.condition_hash,
  // for the Log and the email
  name: row.name, url: row.url, open_url: row.open_url || row.url, condition: row.condition, fetch_mode_used: modeUsed, fetch_status: fetchStatus,
  verdict, confidence, evidence, reason, notify, notify_kind: notifyKind, notify_to: to,
} };
